46	-- SECTION 1 — SUPPLIERS
47	-- Ink and supply vendors, scoped per studio.
48	-- =============================================================
49	
50	CREATE TABLE IF NOT EXISTS public.suppliers (
51	  id             UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
52	  studio_id      UUID        NOT NULL REFERENCES public.studios(id)  ON DELETE CASCADE,
53	  name           TEXT        NOT NULL,
54	  contact_name   TEXT,
55	  email          TEXT,        -- PII:L3
56	  phone          TEXT,        -- PII:L3
57	  website        TEXT,
58	  address        JSONB,
59	  notes          TEXT,
60	  is_active      BOOLEAN     NOT NULL DEFAULT true,
61	  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
62	  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
63	  CONSTRAINT suppliers_studio_name_unique UNIQUE (studio_id, lower(name))
64	);
65	
66	COMMENT ON COLUMN public.suppliers.email        IS 'PII:L3 — vendor contact email, confidential';
67	COMMENT ON COLUMN public.suppliers.phone        IS 'PII:L3 — vendor contact phone, confidential';
68	COMMENT ON COLUMN public.suppliers.contact_name IS 'PII:L3 — vendor contact name, confidential';
69	
70	CREATE INDEX idx_suppliers_studio_id  ON public.suppliers(studio_id);
71	CREATE INDEX idx_suppliers_is_active  ON public.suppliers(studio_id, is_active);
72	
73	CREATE TRIGGER set_suppliers_updated_at
74	  BEFORE UPDATE ON public.suppliers
75	  FOR EACH ROW EXECUTE FUNCTION public.handle_updated_at();
76	
77	ALTER TABLE public.suppliers ENABLE ROW LEVEL SECURITY;
